CREATE TABLE IF NOT EXISTS users(id bigserial PRIMARY KEY,name text NOT NULL,email text UNIQUE NOT NULL,password_hash text NOT NULL,role text NOT NULL CHECK(role IN ('admin','teller','committee','member')),active boolean NOT NULL DEFAULT true,created_at timestamptz DEFAULT now());
CREATE TABLE members(id bigserial PRIMARY KEY,user_id bigint UNIQUE NOT NULL REFERENCES users,number text UNIQUE,nik text UNIQUE NOT NULL,address text NOT NULL DEFAULT '',phone text NOT NULL DEFAULT '',occupation text NOT NULL DEFAULT '',birth_date date,status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','active','rejected','inactive')),reason text,created_at timestamptz DEFAULT now());
CREATE TABLE sessions(id text PRIMARY KEY,user_id bigint NOT NULL REFERENCES users,expires_at timestamptz NOT NULL,revoked boolean DEFAULT false);
CREATE TABLE savings_types(id bigserial PRIMARY KEY,code text UNIQUE NOT NULL,name text NOT NULL,withdrawable boolean NOT NULL DEFAULT false,minimum_balance bigint CHECK(minimum_balance>=0),required_amount bigint CHECK(required_amount>0),active boolean DEFAULT true);
CREATE TABLE savings(id bigserial PRIMARY KEY,member_id bigint REFERENCES members NOT NULL,type_id bigint REFERENCES savings_types NOT NULL,balance bigint NOT NULL DEFAULT 0 CHECK(balance>=0),UNIQUE(member_id,type_id));
CREATE TABLE savings_transactions(id bigserial PRIMARY KEY,member_id bigint REFERENCES members NOT NULL,type_id bigint REFERENCES savings_types NOT NULL,kind text NOT NULL CHECK(kind IN ('deposit','withdrawal')),amount bigint NOT NULL CHECK(amount>0 AND amount<=1000000000000),status text NOT NULL DEFAULT 'pending',note text DEFAULT '',period text,reference text NOT NULL UNIQUE,reason text,verified_by bigint REFERENCES users,created_at timestamptz DEFAULT now());
CREATE UNIQUE INDEX savings_principal_once ON savings_transactions(member_id,type_id) WHERE status='approved' AND period='once';
CREATE UNIQUE INDEX savings_month_once ON savings_transactions(member_id,type_id,period) WHERE status='approved' AND period IS NOT NULL;
CREATE TABLE loan_products(id bigserial PRIMARY KEY,name text NOT NULL,min_amount bigint NOT NULL DEFAULT 1,max_amount bigint NOT NULL DEFAULT 1000000000000,min_tenor int NOT NULL DEFAULT 1,max_tenor int NOT NULL DEFAULT 120,annual_rate_bps bigint,interest_method text CHECK(interest_method IN ('flat','declining')),penalty_daily_amount bigint,penalty_daily_bps bigint,configured boolean NOT NULL DEFAULT false,active boolean DEFAULT true);
CREATE TABLE loan_applications(id bigserial PRIMARY KEY,member_id bigint REFERENCES members NOT NULL,product_id bigint REFERENCES loan_products NOT NULL,amount bigint NOT NULL CHECK(amount>0 AND amount<=1000000000000),tenor int NOT NULL CHECK(tenor BETWEEN 1 AND 120),purpose text NOT NULL,status text NOT NULL DEFAULT 'submitted',survey text,recommendation text,decision_reason text,annual_rate_bps bigint NOT NULL,interest_method text NOT NULL,penalty_daily_amount bigint NOT NULL,penalty_daily_bps bigint NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE loans(id bigserial PRIMARY KEY,application_id bigint UNIQUE NOT NULL REFERENCES loan_applications,member_id bigint NOT NULL REFERENCES members,amount bigint NOT NULL,status text NOT NULL DEFAULT 'active',annual_rate_bps bigint NOT NULL,interest_method text NOT NULL,penalty_daily_amount bigint NOT NULL,penalty_daily_bps bigint NOT NULL,reference text UNIQUE NOT NULL,disbursed_at timestamptz DEFAULT now());
CREATE TABLE installments(id bigserial PRIMARY KEY,loan_id bigint NOT NULL REFERENCES loans,number int NOT NULL,due_date date NOT NULL,principal bigint NOT NULL,interest bigint NOT NULL,penalty bigint NOT NULL DEFAULT 0,status text NOT NULL DEFAULT 'unpaid',paid_at timestamptz,UNIQUE(loan_id,number));
CREATE TABLE payments(id bigserial PRIMARY KEY,installment_id bigint NOT NULL REFERENCES installments,amount bigint NOT NULL,status text NOT NULL DEFAULT 'pending',reference text UNIQUE NOT NULL,reason text,created_at timestamptz DEFAULT now(),verified_at timestamptz);
CREATE UNIQUE INDEX payment_one ON payments(installment_id) WHERE status IN ('pending','approved');
CREATE TABLE ledger(id bigserial PRIMARY KEY,reference text NOT NULL,account text NOT NULL,debit bigint NOT NULL DEFAULT 0 CHECK(debit>=0),credit bigint NOT NULL DEFAULT 0 CHECK(credit>=0),member_id bigint REFERENCES members,description text NOT NULL,created_at timestamptz DEFAULT now(),CHECK((debit=0)<>(credit=0)));
CREATE TABLE audit_logs(id bigserial PRIMARY KEY,actor_id bigint REFERENCES users,action text NOT NULL,entity text NOT NULL,entity_id bigint,"before" jsonb,"after" jsonb,created_at timestamptz DEFAULT now());
CREATE FUNCTION immutable_audit() RETURNS trigger LANGUAGE plpgsql AS $$ BEGIN RAISE EXCEPTION 'Audit logs are append-only'; END $$;
CREATE TRIGGER audit_no_change BEFORE UPDATE OR DELETE ON audit_logs FOR EACH ROW EXECUTE FUNCTION immutable_audit();
CREATE TABLE notifications(id bigserial PRIMARY KEY,user_id bigint NOT NULL REFERENCES users,title text NOT NULL,message text NOT NULL,read boolean NOT NULL DEFAULT false,event_key text UNIQUE,created_at timestamptz DEFAULT now());
CREATE TABLE documents(id bigserial PRIMARY KEY,user_id bigint NOT NULL REFERENCES users,application_id bigint REFERENCES loan_applications,kind text NOT NULL,filename text NOT NULL,path text NOT NULL,mime_type text NOT NULL,size bigint NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE settings(id int PRIMARY KEY DEFAULT 1 CHECK(id=1),shu_configured boolean DEFAULT false,shu_capital_bps int DEFAULT 0,shu_business_bps int DEFAULT 0,shu_basis text DEFAULT 'closing_balance_paid_interest');
INSERT INTO settings(id) VALUES(1);
CREATE TABLE expenses(id bigserial PRIMARY KEY,amount bigint NOT NULL CHECK(amount>0),description text NOT NULL,date date NOT NULL,reference text UNIQUE NOT NULL,created_at timestamptz DEFAULT now());
CREATE TABLE shu_periods(id bigserial PRIMARY KEY,year int UNIQUE NOT NULL,status text DEFAULT 'draft',income bigint DEFAULT 0,expenses bigint DEFAULT 0,distributable bigint DEFAULT 0,capital_bps int,business_bps int,reviewed_by bigint REFERENCES users,finalized_by bigint REFERENCES users,created_at timestamptz DEFAULT now());
CREATE TABLE shu_distributions(id bigserial PRIMARY KEY,period_id bigint NOT NULL REFERENCES shu_periods,member_id bigint NOT NULL REFERENCES members,capital_weight bigint NOT NULL,business_weight bigint NOT NULL,capital_amount bigint NOT NULL,business_amount bigint NOT NULL,total bigint NOT NULL,UNIQUE(period_id,member_id));
